create table public.payments (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, provider text not null, provider_payment_id text, status text not null default 'pending' check(status in ('pending','authorized','captured','failed','cancelled','refunded')), amount_minor bigint not null check(amount_minor >= 0), currency char(3) not null, idempotency_key text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade, unique(store_id,idempotency_key));
create unique index uq_provider_payment on public.payments(provider,provider_payment_id) where provider_payment_id is not null;
